# Maßnahme 12 – Maßnahmenkombinationen: betrieblicher Ausschluss mit „Biologische
# Wirtschaftsweise“ und Einzelflächenkombination gemäß Anhang L.
package oepul.o6_12

organic_partial_farm := object.get(oepul, ["organic_partial_farm"], {})

# Bio-Teilbetrieb mit Kulturbereich Acker und Grünland (MB 5).
organic_partial_farm_arable_grassland if {
	organic_partial_farm.is_partial_farm == true
	organic_partial_farm.organic_culture_area == "arable_grassland"
}

organic_combination_conflict if {
	participates
	"1B" in participating_codes
	not organic_partial_farm_arable_grassland
}

default organic_combination_conflict := false

# --- Anhang L: Einzelflächenkombination ---
anhang_l_cell(a, b) := cell if {
	some cell in data.o6_12.oepul_anhang_l_cells
	cell.row == a
	cell.column == b
}

anhang_l_cell(a, b) := cell if {
	some cell in data.o6_12.oepul_anhang_l_cells
	cell.row == b
	cell.column == a
	not anhang_l_direct(a, b)
}

anhang_l_direct(a, b) if {
	some cell in data.o6_12.oepul_anhang_l_cells
	cell.row == a
	cell.column == b
}

footnote_effect(n) := row.effect if {
	some row in data.o6_12.oepul_anhang_l_footnotes
	row.footnote == n
}

combination_status(other) := "combinable" if {
	cell := anhang_l_cell(measure.code, other)
	cell.marker == "x"
	cell.footnote == null
}

combination_status(other) := "combinable_with_premium_reduction" if {
	cell := anhang_l_cell(measure.code, other)
	cell.marker == "a"
}

combination_status(other) := footnote_effect(cell.footnote) if {
	cell := anhang_l_cell(measure.code, other)
	cell.marker == "x"
	cell.footnote != null
}

combination_status(other) := "not_combinable" if {
	anhang_l_known_measure(other)
	not anhang_l_cell(measure.code, other)
}

combination_status(other) := "unknown_measure_code" if not anhang_l_known_measure(other)

anhang_l_known_measure(code) if {
	some row in data.o6_12.oepul_anhang_l_measures
	row.code == code
}

anhang_l_marker_meaning(marker) := row.meaning if {
	some row in data.o6_12.oepul_anhang_l_markers
	row.marker == marker
}

parcel_combinations := {pid: statuses |
	some p in parcels
	is_woh_parcel(p)
	pid := p.parcel_id
	statuses := {other: combination_status(other) |
		some other in parcel_measure_codes(p)
		other != measure.code
	}
}

parcel_combination_not_permitted contains [pid, other] if {
	some pid, statuses in parcel_combinations
	some other, status in statuses
	status == "not_combinable"
}

# Zuschlag „Einsatz von Organismen oder Pheromonen“ (10) wird bei Teilnahme an 12 um 50 % reduziert.
measure_10_organism_supplement_reduction_percent := data.o6_12.oepul_measure_10_organism_supplement_reduction.reduction_percent if {
	participates
	"10" in participating_codes
}

# Maßnahme 12 – Vertragszeitraum, Beantragung, Ausstieg, Maßnahmenwechsel, Übernahme und
# Flächenänderungen.
package oepul.o6_12

# --- Vertragszeitraum (MB 3.1, AT 5.9, SRL 1.7.1.2) ---
contract_period := row if {
	some row in data.o6_12.o6_12_contract_periods
	row.start_year == commitment_start_year
}

contract_start_valid if contract_period

contract_active_in_year if {
	contract_start_valid
	commitment_start_year <= application_year
	application_year <= year_of(contract_period.end_date)
}

# Letzter Einstieg: Förderjahr 2025 (Beantragung bis 31.12.2024).
contract_findings contains "entry_after_last_entry_year" if {
	participates
	commitment_start_year > measure.last_entry_year
}

contract_findings contains "invalid_commitment_start_year" if {
	participates
	not contract_start_valid
}

# Beantragung im Maßnahmenantrag bis 31.12. vor Vertragsbeginn (MB 5, SRL 1.10.5.2).
application_deadline := sprintf("%d-12-31", [commitment_start_year - 1])

contract_findings contains "measure_application_after_deadline" if {
	participates
	participation_12.application_date > application_deadline
}

# --- Ausstieg (AT 6, SRL 1.10.5.3, 1.7.2) ---
exit_date := object.get(participation_12, "exit_date", null)

exited if exit_date != null

# Ausstieg im laufenden Jahr: Maßnahme im betroffenen Förderjahr nicht mehr gültig.
exit_in_current_year if {
	exited
	year_of(exit_date) == application_year
}

controls := object.get(oepul, ["controls"], {})

# Ausstieg nur bis zur Ankündigung/Durchführung einer VOK bzw. Mitteilung der Verwaltungskontrolle.
exit_blocked_by_control if {
	exited
	controls.on_site_control_announced_or_done == true
}

exit_blocked_by_control if {
	exited
	controls.admin_control_result_notified == true
}

exit_before_contract_end if {
	exited
	exit_date < contract_period.end_date
}

# Rückzahlungsfreie Ausnahmen vom Grundsatz der Rückforderung.
repayment_free_exit_reason contains "leafhopper_exit_2026" if leafhopper_exit_approved

repayment_free_exit_reason contains "switch_to_organic" if switch_valid

repayment_free_exit_reason contains "revision_clause_refused" if {
	object.get(o6_12_input, ["revision_clause_consent_refused"], false) == true
}

repayment_free_exit_reason contains "permanent_circumstances_recognised" if {
	object.get(o6_12_input, ["permanent_circumstances_recognised"], false) == true
}

exit_consequence := "repayment_of_premiums_since_contract_start" if {
	exit_before_contract_end
	count(repayment_free_exit_reason) == 0
}

exit_consequence := "no_repayment" if {
	exit_before_contract_end
	count(repayment_free_exit_reason) > 0
}

# Wiedereinstieg nur mit neuem Maßnahmenantrag; nach dem letzten Einstiegsjahr nicht mehr möglich.
reentry_possible if {
	exited
	application_year < measure.last_entry_year
}

default reentry_possible := false

# --- Maßnahmenwechsel in Biologische Wirtschaftsweise (MB 5, AT 6.2, SRL 1.7.3.2) ---
switch := object.get(o6_12_input, ["switch_to_organic"], {})

switch_valid if {
	switch.requested == true
	switch.effective_date <= measure.switch_to_organic_latest_date
	some row in data.o6_12.oepul_measure_switches
	row.from == measure.code
	measure.switch_to_organic_target_measure in row.to
}

contract_findings contains "switch_to_organic_after_deadline" if {
	switch.requested == true
	switch.effective_date > measure.switch_to_organic_latest_date
}

# --- Maßnahmenübernahme (AT 6.3, SRL 1.7.3.1) ---
takeover := object.get(o6_12_input, ["takeover"], {})

takeover_deadline := sprintf("%d-%s", [application_year, general.takeover_deadline_month_day_2023_2028]) if {
	application_year in {2023, 2028}
}

takeover_deadline := sprintf("%d-%s", [application_year, general.takeover_deadline_month_day]) if {
	not application_year in {2023, 2028}
}

takeover_findings contains "takeover_after_deadline" if {
	takeover.requested == true
	takeover.date > takeover_deadline
}

takeover_findings contains "taker_already_participating" if {
	takeover.requested == true
	takeover.taker_previously_participating == true
}

takeover_findings contains "takeover_expansion_above_50_percent" if {
	takeover.requested == true
	takeover.expansion_percent > general.takeover_max_expansion_percent
}

takeover_findings contains "takeover_not_approved_by_ama" if {
	takeover.requested == true
	takeover.ama_approved == false
}

takeover_valid if {
	takeover.requested == true
	count(takeover_findings) == 0
}

# --- Flächenänderungen ---
# Maßnahme 12: Flächen sind an die jährlich verfügbaren WOH-Flächen gebunden (SRL 1.7.2.5).
area_bound_annually if {
	some row in data.o6_12.oepul_area_bound_annually_measures
	row.measure_code == measure.code
}

# Keine Beschränkung des prämienfähigen Flächenzugangs für Maßnahme 12 (SRL 1.7.2.4).
area_addition_restricted if {
	some row in data.o6_12.oepul_area_addition_restricted_measures
	row.measure_code == measure.code
}

default area_addition_restricted := false

# Toleranz für Flächenverringerungen (SRL 1.7.2.3): 5 %, max. 5 ha, jedenfalls 0,5 ha.
area_reduction_tolerance_ha(previous_area) := max([
	min([(previous_area * general.area_reduction_tolerance_percent) / 100, general.area_reduction_tolerance_max_ha]),
	general.area_reduction_tolerance_min_ha,
])

area_change := object.get(o6_12_input, ["area_change"], {})

area_reduction_ha := area_change.previous_year_area_ha - area_change.current_area_ha

# Nur relevant, wenn die Reduktion nicht auf Verlust der Verfügungsgewalt oder zulässige
# Nutzungsumwandlung zurückgeht und die Maßnahme nicht jährlich flächengebunden ist.
area_reduction_repayment_ha := area_reduction_ha if {
	not area_bound_annually
	area_change.loss_of_disposal_right == false
	area_change.permitted_conversion == false
	area_reduction_ha > area_reduction_tolerance_ha(area_change.previous_year_area_ha)
}

# --- Zahlungsantrag (SRL 1.10.5.3) ---
payment_application := object.get(oepul, ["payment_application"], {})

payment_application_consequence := "commitment_continues_no_payment" if {
	payment_application.submitted == false
	not commitment_start_year == application_year
	object.get(payment_application, "years_overdue", 0) <= general.late_payment_application_max_years
}

payment_application_consequence := "commitment_ends_repayment" if {
	payment_application.submitted == false
	object.get(payment_application, "years_overdue", 0) > general.late_payment_application_max_years
}

# --- Kontrollen (SRL 1.11.1.2) ---
inspection_refused if {
	controls.inspection_refused == true
	not object.get(oepul, ["force_majeure", "recognised"], false)
}

# --- Klassifikation als mehrjährige Maßnahme (SRL 1.7.1.2) ---
is_multi_year_measure if {
	some row in data.o6_12.oepul_multi_year_measures
	row.measure_code == measure.code
}

# Maßnahme 12 ist nicht auf Übernahmen in Einzelfällen beschränkt (AT 6.3).
takeover_restricted_to_single_cases if {
	some row in data.o6_12.oepul_takeover_single_case_only
	contains(row.item, sprintf("(%s)", [measure.code]))
}

default takeover_restricted_to_single_cases := false

# Maßnahme 12 – Gesamtentscheidung: sammelt Verstöße und liefert ein Ergebnisobjekt.
package oepul.o6_12

violations contains {"rule_id": "o6_12.gen.applicant_eligibility", "detail": f} if {
	participates
	some f in applicant_findings
}

violations contains {"rule_id": "o6_12.gen.farm_min_size_first_year", "detail": "farm_min_size_not_met"} if {
	participates
	not farm_min_size_ok
}

violations contains {"rule_id": "o6_12.elig.min_participation_area_first_year", "detail": "woh_area_below_0_5_ha"} if {
	participates
	not min_participation_ok
}

violations contains {"rule_id": "o6_12.oblig.insecticide_ban", "detail": v} if {
	some v in prohibited_insecticide_use
}

violations contains {"rule_id": "o6_12.oblig.authority_order_documentation", "detail": pest} if {
	some pest in authority_order_documentation_missing
}

violations contains {"rule_id": "o6_12.notice2026.designated_area_organic_only", "detail": v} if {
	some v in authority_order_organic_only_breach
}

violations contains {"rule_id": "o6_12.oblig.purchase_storage_ban", "detail": product} if {
	some product in purchase_storage_violation
}

violations contains {"rule_id": "o6_12.psm.psmcsi_required", "detail": v} if {
	some v in psm_code_missing
	v.code == "PSMCSI"
}

violations contains {"rule_id": "o6_12.psm.coding_until_2025", "detail": v} if {
	some v in psm_code_missing
	v.code != "PSMCSI"
}

violations contains {"rule_id": "o6_12.psm.authority_order_upload", "detail": pest} if {
	some pest in authority_order_upload_missing
}

violations contains {"rule_id": "o6_12.psm.advance_coding_correction", "detail": v} if {
	some v in psm_code_without_application
}

violations contains {"rule_id": "o6_12.gen.minimum_management_special_crops", "detail": pid} if {
	some pid in minimum_management_breach
}

violations contains {"rule_id": "o6_12.contract.contract_period", "detail": f} if {
	some f in contract_findings
}

violations contains {"rule_id": "o6_12.comb.no_farm_combination_with_organic", "detail": "organic_measure_1B_without_arable_grassland_partial_farm"} if {
	organic_combination_conflict
}

violations contains {"rule_id": "o6_12.comb.anhang_l_single_area", "detail": {"parcel_id": pid, "measure": other}} if {
	some [pid, other] in parcel_combination_not_permitted
}

violations contains {"rule_id": "o6_12.gen.takeover", "detail": f} if {
	some f in takeover_findings
}

violations contains {"rule_id": "o6_12.gen.exit_timing", "detail": "exit_after_control_announcement"} if {
	exit_blocked_by_control
}

decision := {
	"measure": measure.code,
	"application_year": application_year,
	"participates": participates,
	"woh_area_ha": woh_area_ha,
	"premium_eligible_parcels": premium_eligible_parcel_ids,
	"premium_blocked_reasons": premium_blocked_reason,
	"gross_premium_eur": gross_premium_eur,
	"sanction_reduction_percent": effective_reduction_percent,
	"modulation_factor": modulation_factor,
	"net_premium_eur": net_premium_eur,
	"psm_coding_required": psm_coding_required,
	"leafhopper_exit_approved": leafhopper_exit_approved,
	"violations": violations,
}

# Maßnahme 12 – Zugangs- und Fördervoraussetzungen: Förderwerbende Person, Betriebsmindestgröße, Mindestteilnahmefläche und Förderfähigkeit von Schlägen.
package oepul.o6_12

applicant := object.get(input, ["farm", "applicant"], {})

# --- Förderwerbende Personen (SRL 1.4, AT 5.2) ---
applicant_type_row := row if {
	some row in data.o6_12.oepul_eligible_applicant_types
	row.person_type == applicant.person_type
}

public_body_exception_applies if {
	some row in data.o6_12.oepul_public_body_exception_measures
	row.measure_code == measure.code
	row.year_from <= application_year
	object.get(row, "year_to", null) == null
}

public_body_exception_applies if {
	some row in data.o6_12.oepul_public_body_exception_measures
	row.measure_code == measure.code
	row.year_from <= application_year
	row.year_to >= application_year
}

applicant_findings contains "applicant_type_not_eligible" if {
	applicant.person_type
	not applicant_type_row
	not public_body_exception_applies
}

applicant_findings contains "public_body_share_above_25_percent" if {
	max_share := applicant_type_row.max_public_body_share_percent
	max_share != null
	object.get(applicant, "public_body_share_percent", 0) > max_share
	not public_body_exception_applies
}

applicant_findings contains "not_active_farmer" if {
	applicant.is_active_farmer == false
}

applicant_findings contains "no_agricultural_activity" if {
	applicant.performs_agricultural_activity == false
}

applicant_findings contains "not_farming_in_own_name_and_account" if {
	applicant.farms_in_own_name_and_account == false
}

applicant_eligible if count(applicant_findings) == 0

# --- Betriebsmindestgröße im 1. ÖPUL-Teilnahmejahr (SRL 1.6.1, AT 5.3) ---
first_oepul_year := object.get(oepul, ["first_participation_year"], null)

farm_min_size_required if first_oepul_year == application_year

farm_min_size_met if {
	object.get(input, ["land", "protected_cultivation_area_ha"], 0) >= general.farm_min_protected_cultivation_ha
}

farm_min_size_met if {
	input.land.total_area_ha >= general.farm_min_agricultural_area_ha
}

farm_min_size_ok if not farm_min_size_required

farm_min_size_ok if {
	farm_min_size_required
	farm_min_size_met
}

# --- Mindestteilnahmefläche 0,50 ha WOH im 1. Verpflichtungsjahr (SRL 2.12, MB 3.2) ---
first_commitment_year_is_current if commitment_start_year == application_year

min_participation_ok if not first_commitment_year_is_current

min_participation_ok if {
	first_commitment_year_is_current
	woh_area_ha >= measure.min_participation_area_first_year_ha
}

# --- Zugangsvoraussetzungen gesamt ---
access_requirements_met if {
	applicant_eligible
	farm_min_size_ok
	min_participation_ok
}

# Folge nicht erfüllter Zugangsvoraussetzungen (SRL 1.12.1.1).
access_failure_consequence := "no_contract" if {
	not access_requirements_met
	first_commitment_year_is_current
}

access_failure_consequence := "no_premium_current_year" if {
	not access_requirements_met
	not first_commitment_year_is_current
}

# --- Förderfähigkeit der Einzelschläge ---
parcel_ineligible contains [p.parcel_id, "not_wine_fruit_hop_area"] if {
	some p in parcels
	not is_woh_parcel(p)
}

parcel_ineligible contains [p.parcel_id, "use_type_not_premium_eligible"] if {
	some p in parcels
	is_woh_parcel(p)
	not type_info(p).premium_eligible
}

parcel_ineligible contains [p.parcel_id, "fruit_crop_not_in_oepul_fruit_list"] if {
	some p in parcels
	fruit_crop_not_listed(p)
}

parcel_ineligible contains [p.parcel_id, "fruit_not_grafted_planting_material"] if {
	some p in parcels
	woh_type(p) == "fruit"
	object.get(p, ["crop", "fruit_grafted"], null) == false
}

parcel_ineligible contains [p.parcel_id, "op_code_set"] if {
	some p in parcels
	some code in parcel_op_codes(p)
	code == "OP"
}

parcel_ineligible contains [p.parcel_id, "measure_specific_op_code_set"] if {
	some p in parcels
	object.get(p, ["oepul", "measure_op_code_o6_12"], false) == true
}

parcel_ineligible contains [p.parcel_id, "located_outside_austria"] if {
	some p in parcels
	object.get(p, ["location", "in_austria"], true) == false
}

parcel_ineligible contains [p.parcel_id, "national_park_without_area_premiums"] if {
	some p in parcels
	np := object.get(p, ["location", "national_park"], null)
	some row in data.o6_12.oepul_national_park_rules
	row.national_park == np
	row.area_premiums_granted == false
	not measure.code in row.exempt_measures
}

parcel_ineligible contains [p.parcel_id, "scientific_trial_area_vf"] if {
	some p in parcels
	object.get(p, ["oepul", "trial_area_vf"], false) == true
}

parcel_ineligible contains [p.parcel_id, "gloez_landscape_element"] if {
	some p in parcels
	object.get(p, ["oepul", "is_gloez_landscape_element"], false) == true
}

parcel_ineligible contains [p.parcel_id, "not_declared_for_measure"] if {
	some p in parcels
	object.get(p, ["oepul", "declared_for_o6_12"], true) == false
}

parcel_ineligible contains [p.parcel_id, "transferred_without_continuation"] if {
	some p in parcels
	object.get(p, ["oepul", "transferred_during_year"], false) == true
	object.get(p, ["oepul", "successor_continues_commitment"], false) == false
}

parcel_ineligible contains [p.parcel_id, "minimum_management_not_met"] if {
	some p in parcels
	some key in ["proper_planting", "annual_care", "harvest_and_removal"]
	object.get(p, ["operations", "minimum_management", key], true) == false
}

parcel_ineligible contains [p.parcel_id, "not_actively_farmed"] if {
	some p in parcels
	object.get(p, ["operations", "actively_farmed"], true) == false
}

parcel_ineligible_reasons := {pid: reasons |
	some p in parcels
	pid := p.parcel_id
	reasons := {r | some [id, r] in parcel_ineligible; id == pid}
}

premium_eligible_parcel(p) if {
	is_woh_parcel(p)
	count(parcel_ineligible_reasons[p.parcel_id]) == 0
}

premium_eligible_parcel_ids contains p.parcel_id if {
	some p in parcels
	premium_eligible_parcel(p)
}

# Maßnahme 12 – Sonderregelungen 2026: rückzahlungsfreier Ausstieg wegen Amerikanischer
# Rebzikade, Bekämpfung in verordneten Gebieten sowie Meldung höherer Gewalt (Trockenheit).
package oepul.o6_12

leafhopper_exit := object.get(o6_12_input, ["leafhopper_exit"], {})

leafhopper_exit_request_date := leafhopper_exit.request_date

leafhopper_exit_findings contains "exit_before_2026_not_covered" if {
	leafhopper_exit.requested == true
	year_of(leafhopper_exit.request_date) < measure.leafhopper_repayment_free_exit_from_year
}

leafhopper_exit_findings contains "farm_has_no_wine_area" if {
	leafhopper_exit.requested == true
	not farm_has_wine_area
}

leafhopper_exit_findings contains "reason_leafhopper_not_stated" if {
	leafhopper_exit.requested == true
	object.get(leafhopper_exit, "reason_leafhopper_stated", false) == false
}

leafhopper_exit_findings contains "not_submitted_via_force_majeure_form" if {
	leafhopper_exit.requested == true
	object.get(leafhopper_exit, "submitted_via_eama_force_majeure_form", false) == false
}

leafhopper_exit_eligible if {
	participates
	leafhopper_exit.requested == true
	count(leafhopper_exit_findings) == 0
}

leafhopper_exit_approved if {
	leafhopper_exit_eligible
	object.get(leafhopper_exit, "approved", true) != false
}

default leafhopper_exit_approved := false

# Vertragszeitraum endet mit Beginn der einzelbetrieblichen Meldung.
contract_end_after_leafhopper_exit := leafhopper_exit_request_date if leafhopper_exit_approved

# --- Verordnete Bekämpfung in festgelegten Gebieten (ST, B, NÖ) ---
designated_area_orders contains o if {
	some o in authority_orders
	o.federal_state in measure.leafhopper_order_states
	o.in_designated_area == true
}

# Verbleib ohne Prämieneinbußen, wenn CS-Wirkstoff angeordnet bzw. keine Bio-Wirkstoffe verfügbar.
designated_area_chemical_synthetic_permitted if {
	some o in designated_area_orders
	order_covers_chemical_synthetic(o)
}

# Übermittlung der Anordnung an die AMA ab 2026 nicht erforderlich (Codierung entfallen).
authority_order_submission_to_ama_required if psm_coding_required

default authority_order_submission_to_ama_required := false

# --- Höhere Gewalt (SRL 1.7.4.1; Notice Trockenheit 2026) ---
